<?php declare(strict_types=1);
if($financeMatchState['error']!==''):?><p class="error" role="alert"><?=e($financeMatchText($financeMatchState['error']))?></p><?php endif;
if($financeMatchBody):
$financeMatchAction=input($financeMatchBody,'action');$financeMatchSource=null;$financeMatchTarget=null;
try{$financeMatchSource=$finance->transactionDetail(input($financeMatchBody,'transaction_id'));}catch(DomainException){}
try{$financeMatchTarget=match($financeMatchAction){'allocate'=>$finance->entry(input($financeMatchBody,'entry_id')),'internal-link'=>$finance->transactionDetail(input($financeMatchBody,'other_id')),'internal-cash'=>$finance->account(input($financeMatchBody,'cash_account'))};}catch(DomainException){}
?>
<section class="card finance-match-original" id="finance-match-original" data-finance-match-original>
<h2><?=e($financeMatchText('Auswahl und Eingaben'))?></h2>
<p><?=e($financeMatchText('Die ursprüngliche Auswahl bleibt erhalten. Prüfe den bisherigen Ausgang im Verlauf. Eine bereits gespeicherte Zuordnung wird durch ihre identische Wiederholung nicht erneut angelegt.'))?></p>
<?php if($financeMatchState['restored']):?><p role="status"><?=e($financeMatchText('Ursprüngliche Auswahl wieder aufgenommen. Die Angaben wurden dadurch nicht gebucht.'))?></p><?php endif?>
<?php if($financeMatchState['draft']['reviewed']??false):?><p class="notice" role="status"><?=e($financeMatchText('Aktueller Stand ausdrücklich gelesen. Beträge und Quellen vergleichen und anschließend gesondert speichern.'))?></p><?php endif?>
<dl class="data-list"><dt><?=e($financeMatchText('Umsatz'))?></dt><dd><?php if($financeMatchSource):?><a href="<?=e(url(bankTransactionContext($financeMatchSource['id'],$_GET)))?>"><?=e($financeMatchSource['account_name'].' · '.dateDe($financeMatchSource['booked_on']).' · '.euro((int)$financeMatchSource['cents']).' · '.$financeMatchSource['description'])?></a><?php else:echo e($financeMatchText('Ausgewählte Quelle derzeit nicht verfügbar. Ihre ursprüngliche Auswahl wurde nicht ersetzt.'));endif?></dd>
<dt><?=e($financeMatchText(match($financeMatchAction){'allocate'=>'Ursprünglich gewählter Beleg','internal-link'=>'Ursprünglich gewählter Gegenumsatz','internal-cash'=>'Ursprünglich gewählte Handkasse'}))?></dt><dd><?php if($financeMatchTarget):echo e(match($financeMatchAction){'allocate'=>($financeMatchTarget['display_number']??'').' · '.$financeMatchTarget['description'],'internal-link'=>$financeMatchTarget['account_name'].' · '.dateDe($financeMatchTarget['booked_on']).' · '.$financeMatchTarget['description'],'internal-cash'=>$financeMatchTarget['name']});else:echo e($financeMatchText('Ausgewählte Quelle derzeit nicht verfügbar. Ihre ursprüngliche Auswahl wurde nicht ersetzt.'));endif?></dd>
<?php if($financeMatchSource):?><dt><?=e($financeMatchText('Am Umsatz noch zuzuordnen'))?></dt><dd><?=e(euro((int)$financeMatchSource['remaining_cents']))?></dd><?php endif?>
<?php if($financeMatchTarget&&$financeMatchAction!=='internal-cash'):?><dt><?=e($financeMatchText($financeMatchAction==='allocate'?'Am Beleg noch offen':'Am Umsatz noch zuzuordnen'))?></dt><dd><?=e(euro((int)$financeMatchTarget['remaining_cents']))?></dd><?php endif?></dl>
<?php if($finance->canWrite()):?>
<form method="post" id="finance-match-original-form" class="finance-match-original-form" data-finance-match-form>
<?=csrf()?><?php foreach($financeMatchBody as $field=>$value)if(!in_array($field,['amount','reason','cash_date','cash_confirm','match_draft','csrf','review_match'],true)&&is_string($value))echo hidden($field,$value);if($financeMatchNonce!=='')echo hidden('match_draft',$financeMatchNonce);?>
<label><?=e($financeMatchText(match($financeMatchAction){'allocate'=>'Zuordnen (EUR)','internal-link'=>'Transferbetrag (EUR)','internal-cash'=>'Bargeldbetrag (EUR)'}))?><input class="form-control" name="amount" inputmode="decimal" required value="<?=e(input($financeMatchBody,'amount'))?>"></label>
<?php if($financeMatchAction!=='allocate'):?><label><?=e($financeMatchText('Grund / Nachweis'))?><textarea class="form-control" name="reason" required maxlength="2000" aria-describedby="finance-match-reason-help"><?=e(input($financeMatchBody,'reason'))?></textarea><small id="finance-match-reason-help"><?=e($financeMatchText('Höchstens 500 Zeichen.'))?></small></label><?php endif?>
<?php if($financeMatchAction==='internal-cash'):?><label><?=e($financeMatchText('Tag der tatsächlichen Bargeldbewegung'))?><input class="form-control" type="date" name="cash_date" required value="<?=e(input($financeMatchBody,'cash_date'))?>" max="<?=e(date('Y-m-d'))?>"></label><label class="finance-match-confirm"><input type="checkbox" name="cash_confirm" value="1" required <?=input($financeMatchBody,'cash_confirm')==='1'?'checked':''?>><span><?=e($financeMatchText('Die Bargeldbewegung ist tatsächlich erfolgt und noch nicht im Kassenbuch erfasst.'))?></span></label><?php endif?>
<div class="actions"><button class="btn btn-outline theme-secondary" name="match_move" value="all:search" formnovalidate><?=e($financeMatchText('Eingaben behalten und Suche aktualisieren'))?></button><button class="btn btn-solid theme-primary"><?=e($financeMatchText('Ursprüngliche Zuordnung speichern oder ihren Ausgang erneut lesen'))?></button><button class="btn btn-outline theme-secondary" name="review_match" value="1" formnovalidate><?=e($financeMatchText('Aktuellen Stand ausdrücklich prüfen'))?></button></div></form>
<?php if($financeMatchNonce!==''):?><form method="post" class="finance-match-close"><?=csrf().hidden('action','finance-match-discard').hidden('match_draft',$financeMatchNonce)?><button class="btn btn-outline theme-secondary"><?=e($financeMatchText('Ursprüngliche Auswahl bewusst schließen'))?></button></form><?php endif?>
<?php else:?><p><?=e(input($financeMatchBody,'amount'))?></p><?php if(isset($financeMatchBody['reason'])):?><p><?=e($financeMatchBody['reason'])?></p><?php endif;endif?>
<p><a class="btn btn-outline theme-secondary" href="<?=e(url($financeMatchFreshContext))?>"><?=e($financeMatchText('Neue Auswahl beginnen'))?></a></p>
</section>
<?php endif?>
<?php if($financeMatchState['originals']):?><details class="card finance-match-resume"><summary><?=e($financeMatchText('Weitere ursprüngliche Auswahlen'))?></summary><?php foreach($financeMatchState['originals'] as $financeMatchIndex=>$financeMatchOriginal):if($financeMatchOriginal['id']===$financeMatchNonce)continue;?><p><a class="btn btn-outline theme-secondary" href="<?=e(url(array_replace($financeMatchFreshContext,['match_draft'=>$financeMatchOriginal['id']])))?>"><?=e($financeMatchText('Ursprüngliche Auswahl {number} fortsetzen',['number'=>$financeMatchIndex+1]))?> · <?=e($financeMatchText(match($financeMatchOriginal['action']){'allocate'=>'Belegzuordnung','internal-link'=>'Eigener Geldtransfer','internal-cash'=>'Tatsächliche Bargeldbewegung'}))?></a></p><?php endforeach?></details><?php endif?>
